css:
.lsp-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsp-root,.lsp-root *,.lsp-root *::before,.lsp-root *::after{box-sizing:border-box}
.lsp-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsp-root img{display:block;border:0;max-width:none}
.lsp-root [hidden]{display:none!important}
.lsp-root .nS5_124_1920{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;place-items:start;position:relative;flex-shrink:0}
.lsp-root .nS5_124_1921{grid-column:1;height:98px;margin-left:0;margin-top:0;position:relative;grid-row:1;width:124px}
.lsp-root .x500001{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsp-root .nS5_124_1922{grid-column:1;align-content:stretch;display:flex;flex-direction:column;height:23px;align-items:flex-start;justify-content:center;margin-left:2px;margin-top:1.9px;padding-bottom:5px;padding-left:5px;padding-right:12px;padding-top:4px;position:relative;border-bottom-right-radius:100px;border-top-right-radius:100px;grid-row:1;border-style:solid;border-color:var(--wa-point, #5468c0);border-width:1px;background-image:linear-gradient(to left,var(--wa-point, #011056),color-mix(in srgb, var(--wa-point, rgb(1 16 86)) 0%, transparent))}
.lsp-root .nS5_124_1923{align-content:stretch;display:flex;gap:6px;align-items:center;position:relative;flex-shrink:0}
.lsp-root .nS5_124_1924{height:11px;position:relative;flex-shrink:0;width:10px}
.lsp-root .x500002{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsp-root .nS5_124_1925{word-break:break-word;font-family:"NanumSquare","Pretendard",sans-serif;font-weight:700;line-height:14px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text, #fefeff);font-size:12px;white-space:nowrap;width:22px}
.lsp-root .nS5_124_1926{word-break:break-word;grid-column:1;align-content:stretch;display:flex;gap:4px;align-items:baseline;justify-content:center;line-height:normal;margin-left:25px;margin-top:42.9px;font-style:normal;position:relative;grid-row:1;color:var(--wa-text, #fff);white-space:nowrap}
.lsp-root .nS5_124_1927{font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;position:relative;flex-shrink:0;font-size:28px;width:49px;line-height:33px;white-space:nowrap}
.lsp-root .nS5_124_1928{font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;position:relative;flex-shrink:0;font-size:16px;width:21px;line-height:19px;white-space:nowrap}
.lsp-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsp-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsp-root [data-node-id="124:1922"]{border-color:transparent!important}
.lsp-root [data-node-id="124:1922"]::after{content:"";position:absolute;inset:-1px;border-radius:inherit;padding:1px;pointer-events:none;-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;background:linear-gradient(270deg,var(--wa-point, rgba(84,104,192,1)) 0%,color-mix(in srgb, var(--wa-point, rgb(22 56 151)) 0%, transparent) 100%)}
.lsp-root [data-node-id="124:1931"]{border-color:transparent!important}
.lsp-root [data-node-id="124:1931"]::after{content:"";position:absolute;inset:-1px;border-radius:inherit;padding:1px;pointer-events:none;-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;background:linear-gradient(270deg,var(--wa-point, rgba(84,104,192,1)) 0%,color-mix(in srgb, var(--wa-point, rgb(22 56 151)) 0%, transparent) 100%)}
.lsp-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.lsp-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsp-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsp-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsp-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsp-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsp-root[data-theme="light"] .nS5_124_1922{border-color:var(--wa-point, #7a88c2)}
.lsp-root[data-theme="light"] .nS5_124_1926{color:var(--wa-text, #10231d)}
